xfs_buf_t* xfs_buf_search(struct xfs_buftarg *btp, struct xfs_buf_map *map, int nmaps, xfs_buf_flags_t flags, xfs_buf_t *new_bp) {
    xfs_buf_t *bp = NULL;
    int i;

    if (!btp || !map || nmaps <= 0 || !new_bp) {
        return NULL;
    }

    for (i = 0; i < nmaps; i++) {
        if (map[i].bm_bn == 0 || map[i].bm_len <= 0) {
            return NULL;
        }
    }

    /* Search for a matching buffer in the cache. */
    bp = xfs_buf_find(btp, map, nmaps, flags);

    if (bp) {
        if (bp->b_flags & XBF_STALE) {
            xfs_buf_stale(bp);
        }
        if (xfs_buf_lock(bp)) {
            return NULL;
        }
    } else {
        if (xfs_buf_insert(btp, new_bp)) {
            return NULL;
        }
        bp = new_bp;
    }

    return bp;
}
